racts/supplier-forager-pulse.rml","ops/systemd","test/clock-contract.test.mjs"],"readablePaths":[],"protectedOrExcluded":["paths outside territory","undeclared writable paths when writablePaths is nonempty",".git","node_modules",".lake","dist","coverage","operational data records unless the objective names them"]},"targetArtifacts":[{"path":"content/contracts/supplier-forager-pulse.rml","status":"must-create"},{"path":"ops/systemd","status":"must-create"},{"path":"test/clock-contract.test.mjs","status":"must-create"}],"evidenceArtifacts":[{"path":"AGENTS.md","role":"territory-instructions","digest":"sha256:6f688beca28145b29eeab6e1649f4a8f047d21c7e7f7713a21f257da0318a6bd","bytes":1138,"truncated":false,"text":"# Executive Office Sovereign Improvement Board\n\nThis settlement is one customer-owned improvement board for the Executive\nOffice. It is an instance of a board pattern, not the Union's board, a global\nwork pool, a supplier runtime, or a preferred implementation.\n\n- The board turns exact customer observations into provider-neutral work lots.\n- It publishes buyer-authored bounty quotes and accepts independently authored\n  supplier bids. It never writes a supplier's bid or chooses how a supplier\n  performs work.\n- Bounties age only inside this board's book. A capped lot with no qualified\n  bidder emits a capability-gap observation; it never causes model escalation.\n- A supplier may deliver proposal bytes only. review and exact\n  replay belong to distinct actors, and the customer alone applies accepted\n  bytes to its own territory.\n- Clockkeeper may pulse `advance-board`; the pulse does not own the board, its\n  work, its prices, its awards, or its customer decisions.\n- Durable acts are normalized typed RMN and are appended through the hired\n  RWIL/RDF provider. ActivityStreams is the inter-enterprise projection.\n\n"},{"path":"package.json","role":"package-manifest","digest":"sha256:e470b9a8e8d9e9491a22975250a1285ab304cf7f97db5841cb55feaf46b2f839",